from pathlib import Path
import json,re
R=Path('/workspace/work/deliverables/confluence/review');C=R.parent/'collection/confluence';(R/'reassembled').mkdir(exist_ok=True)
# These are library-level refinements, never page-local design overrides.
f=C/'foundation/foundation.css';s=f.read_text();s+='''.cover .title small{display:block;font-size:var(--type-44);font-weight:var(--lead-weight);line-height:var(--lead-line);letter-spacing:var(--lead-track);color:var(--n-7);margin-bottom:var(--gap-sm)}.cover .title{font-size:var(--type-128);line-height:var(--figure-line)}.cover .lead{font-size:var(--type-16)}.head.center{padding-top:calc(var(--gap-lg)*2 + var(--gap-sm))}.head.center .title{font-size:var(--type-64)}.top .seat.icon{position:absolute;left:50%;top:0;transform:translateX(-50%);width:160px;height:126px}.rail .title{font-size:var(--type-60)}.rail .seat{width:130px;height:145px;margin-bottom:var(--gap)}.rail .lead{font-size:var(--type-14);margin-top:var(--gap)}.rail .kicker{margin-top:var(--gap-sm)}\n'''
f.write_text(s)
f=C/'kit/css/tokens.css';s=f.read_text().replace('--margin-x: 72px','--margin-x: 94px').replace('--rail-gap: 40px','--rail-gap: 86px');f.write_text(s)
f=C/'elements/card/element.css';s=f.read_text();q='.card[data-el="confluence-card"]';s+=f'''{q} .kick{{background:var(--a1);color:var(--a1-on);padding:var(--gap-sm);border-radius:var(--radius-sm);font-size:var(--type-22);letter-spacing:var(--name-track)}}{q} .parts{{grid-template-rows:auto auto auto 1fr;align-self:stretch;align-content:center}}{q}:has(.kick):not(:has(.fig)) .parts{{display:flex;align-items:center;gap:var(--gap)}}{q}:has(.kick):not(:has(.fig)) .kick{{align-self:stretch;flex:1;display:flex;align-items:center;justify-content:center;text-align:center;background:var(--a2);color:var(--a2-on)}}{q}:has(.kick):not(:has(.fig)) .name{{flex:2;border:0;font-size:var(--type-28);text-align:left;align-self:center}}{q} .parts>.note{{align-self:center}}\n''';f.write_text(s)
f=C/'elements/hub/element.css';s=f.read_text();q='.hub[data-el="confluence-hub"]';s+=f'''{q} .core{{grid-row:1 / span 3;align-self:center;aspect-ratio:1;height:auto;border-width:16px}}{q} .spoke{{background:none;align-items:flex-start;justify-content:center;text-align:left;padding:0}}{q} .spoke:nth-child(3),{q} .spoke:nth-child(5){{align-items:flex-end;text-align:right}}{q} .spoke .name{{font-size:var(--type-32)}}{q} .spoke .name b{{color:var(--a2)}}{q} .spoke:nth-child(3) .name b,{q} .spoke:nth-child(4) .name b{{color:var(--a1)}}{q} .spoke .note{{font-size:var(--type-14)}}{q} .spoke .mark .icon{{width:64px;height:64px}}{q} .core .name{{font-size:var(--type-52)}}{q} .core .note{{color:var(--a1-on);font-size:var(--type-14);padding:0 var(--pad)}}\n''';f.write_text(s)
# Reference style supplies palette values; it contains no layout or component rules.
pal=json.loads(Path('/workspace/work/reference/contract/palette.json').read_text())['light']
pal.update({'--a1':'#41c6db','--a1-on':'#082d36','--a2':'#3a54df','--a2-on':'#ffffff','--n-7':'#667078','--n-2':'#e1e4e6','--a1-1-soft':'#effbfc','--a2-1-soft':'#f0f2fd'})
(R/'assets/reference-style.css').write_text('.slide{'+''.join(k+':'+v+';' for k,v in pal.items())+'}\n')
steps=json.loads(Path('/workspace/work/reference/contract/type-steps.json').read_text());(R/'assets/type-steps.css').write_text('.slide{'+''.join(f'--type-{n}:{n}px;' for n in steps)+'}\n')
# Runtime icons fill only empty, contracted Lucide seats, matching Rhetis rendering behaviour.
(R/'assets/icons.js').write_text('''document.addEventListener('DOMContentLoaded',()=>{const paths={'chart-no-axes-combined':'<path d="M3 3v18h18M7 14v3m5-6v6m5-10v10M5 9l5-5 4 3 6-5m-4 0h4v4"/>','messages-square':'<path d="M3 3h14v11H8l-4 4v-4H3zM10 8h11v12h-4l-4 3v-3h-3z"/><path d="M12 12h.1m4 0h.1m3 0h.1"/>','mail':'<path d="M3 7l9-5 9 5v14H3zM3 7l9 9 9-9M6 10V3h12v7M9 6h6"/>','arrow-down-up':'<path d="M7 21V3m-4 4 4-4 4 4m6-4v18m-4-4 4 4 4-4"/>'};for(let e of document.querySelectorAll('[data-icon]')){let v=paths[e.dataset.icon]||'<circle cx="12" cy="12" r="9"/><path d="M8 12h8m-4-4v8"/>';e.innerHTML='<svg viewBox="0 0 24 24" width="100%" height="100%" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">'+v+'</svg>'}});''')
links=['../assets/fonts/fonts.css','../../collection/confluence/kit/css/tokens.css','../assets/reference-style.css','../assets/type-steps.css','../../collection/confluence/foundation/foundation.css']+['../../collection/confluence/elements/'+d.name+'/element.css' for d in sorted((C/'elements').iterdir())]
def pg(i,body):
 head=''.join(f'<link rel="stylesheet" href="{x}">' for x in links)
 (R/'reassembled'/f'slide_{i:02}.html').write_text(f'<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>Confluence Reassembled {i}</title>{head}<script src="../assets/icons.js"></script></head><body>{body}</body></html>')
def el(root,folder,content,grid='',variant='',data=''):
 st=f' style="{grid}{data}"' if grid or data else ''
 return f'<div class="{root} {variant}" data-el="confluence-{folder}"{st}>{content}</div>'
def card(kick,fig,name,note,grid):return el('card','card',f'<div class="parts"><p class="kick">{kick}</p><p class="name">{name}</p><p class="fig">{fig}</p><p class="note">{note}</p></div>',grid)
pg(1,'''<section class="slide cover"><div class="page"><div class="seat back" data-ph="1"></div><div class="lockup at-left"><p class="kicker">INDUSTRY-ACADEMIC COOPERATION PROPOSAL</p><h1 class="title"><small>회사와 교육기관을 위한</small><b>산학</b><b>협력</b><br>제안서</h1><p class="lead">여러 기관에서 두루 쓰이는 <b>산학 협력 프로젝트 제안 프레젠테이션</b></p></div></div></section>''')
entries=''.join(f'<div class="entry"><span class="mark">{i+1:02}</span><b class="name">{n}</b><p class="note">타이틀에 대한 간략한 2~3줄 정도의 설명글이 들어가는 영역입니다.</p></div>' for i,n in enumerate(['프로젝트 개요','프로젝트 목표','제안 내용','기대 효과','주요 일정','요약 보기']))
pg(2,'<section class="slide"><div class="top"><div class="seat icon" data-ph="1"></div></div><div class="page"><header class="head center"><h1 class="title"><b>목차</b>보기</h1><p class="kicker">TABLE OF INDEX</p></header><div class="body">'+el('agenda','agenda',entries,'grid-column:1 / span 12; grid-row:1 / span 6')+'</div></div></section>')
header=el('card','card','<div class="parts"><p class="kick">프로젝트 명</p><p class="name">해당 프로젝트의 이름을 입력하세요.</p></div>','grid-column:1 / span 12; grid-row:1 / span 1')
items=card('프로젝트 기간','2060년 4월 26일<br>~ 6월 18일 (50일간)','전체기간','<b>1차 프로젝트</b><br>2060년 4월 26일~ 5월 17일<br><br><b>2차 프로젝트</b><br>2060년 5월 18일~ 6월 18일','grid-column:1 / span 4; grid-row:2 / span 5')+card('프로젝트 예산','2억 5천','총액','<b>사업관리비</b><br>127,500,600원<br><br><b>연계지원비</b><br>130,640,100원','grid-column:5 / span 4; grid-row:2 / span 5')+card('참여 인원','김미리','책임자','<b>연구원</b><br>이미리 / 과제 진행<br>김미리 / 과제 진행<br>박미리 / 모델 개발<br>신미리 / 모델 개발','grid-column:9 / span 4; grid-row:2 / span 5')
pg(3,'<section class="slide"><div class="rail"><div class="seat" data-ph="1"></div><h1 class="title"><b>프로젝트</b><br>개요</h1><p class="kicker">PROJECT OUTLINE</p><p class="lead">메인타이틀에 대한 간략한 세부 설명을 입력하는 영역입니다.<br>내용을 입력해주세요.</p></div><div class="page"><div class="body">'+header+items+'</div></div></section>')
core='<div class="core"><b class="name">프로젝트<br>목표</b><p class="note">PROJECT GOAL<br><br>메인타이틀에 대한 간략한 설명을 입력하는 영역입니다.</p></div>'
icons=['chart-no-axes-combined','messages-square','mail','arrow-down-up'];spokes=''
for i,icon in enumerate(icons):spokes+=f'<div class="spoke"><span class="mark"><span class="icon" data-icon="{icon}"></span></span><b class="name">프로젝트 목표 <b>{i+1:02}</b></b><p class="note">프로젝트 목표를 입력하세요.<br>이 페이지는 <b>프로젝트 목표</b>를 입력하는 페이지입니다.<br>프로젝트의 상세 목표를 입력하세요.<br>이 페이지는 프로젝트 목표를 입력해 주세요.</p></div>'
pg(4,'<section class="slide"><div class="page"><div class="body">'+el('hub','hub',core+spokes,'grid-column:1 / span 12; grid-row:1 / span 6')+'</div></div></section>')
print('Reassembled four pages using collection styles only')
